"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[36276],{17092:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>i,metadata:()=>o,toc:()=>l});const o=JSON.parse('{"id":"tangfen/abasicquestion","title":"","description":"[Dushulang] actually went and posted a dedicated thread \\"[Tangfen], don\'t dodge the question -- tell us what is the dimension of Marx\'s \'value\'? And what is the dimension of \'labor\'?\\" to ask a kindergarten-level question about Marx. By kindergarten-level, I don\'t mean these people are kindergarteners; it\'s a metaphor for how this question is the most elementary common knowledge about Marx, one that shouldn\'t raise any doubts at all. Yet now these anti-Marx people don\'t even know this, which also proves from one angle that these people who oppose Marx have never actually understood Marx!","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/abasicquestion.md","sourceDirName":"tangfen","slug":"/tangfen/abasicquestion","permalink":"/en/tangfen/abasicquestion","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"abasicquestion","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"\u4ece[\u8bfb\u4e66\u72fc]\u56de\u5e16\u8bf4\u8d77\uff1a\u8bf7\u5927\u5bb6\u9605\u8bfb\u65f6\u8981\u8ba4\u771f\u70b9\uff0c\u4e0d\u8981\u8fde\u522b\u4eba\u7684\u610f\u601d\u90fd\u7406\u89e3\u53cd\u4e86","permalink":"/en/tangfen/aboutdslreply"},"next":{"title":"\u4e00\u5802\u5e7c\u513f\u56ed\u7269\u7406\u8bfe\uff0c\u518d\u7ed9\u4e91\u8c37\u5b50\u4e4b\u6d41\uff01","permalink":"/en/tangfen/abasicphysicslecture"}}');var a=n(74848),s=n(28453);const i={id:"abasicquestion",title:"",hide_table_of_contents:!0},r="Explaining a Kindergarten-Level Question About Marx to the Likes of [Dushulang]!",h={},l=[];function c(e){const t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"explaining-a-kindergarten-level-question-about-marx-to-the-likes-of-dushulang",children:"Explaining a Kindergarten-Level Question About Marx to the Likes of [Dushulang]!"})}),"\n",(0,a.jsx)(t.p,{children:"[Dushulang] actually went and posted a dedicated thread \"[Tangfen], don't dodge the question -- tell us what is the dimension of Marx's 'value'? And what is the dimension of 'labor'?\" to ask a kindergarten-level question about Marx. By kindergarten-level, I don't mean these people are kindergarteners; it's a metaphor for how this question is the most elementary common knowledge about Marx, one that shouldn't raise any doubts at all. Yet now these anti-Marx people don't even know this, which also proves from one angle that these people who oppose Marx have never actually understood Marx!"}),"\n",(0,a.jsx)(t.p,{children:'The dimension of Marx\'s "value" is the dimension of currency. What we commonly call the yuan of RMB and the dollar of USD all belong to units of currency, and dimension is something more fundamental than units. Like centimeters and millimeters are both units of length, but both belong to the dimension of length, generally represented by L. The yuan of RMB and the dollar of USD, these specific currency units, all belong to the dimension of currency, and the dimension of Marx\'s "value" is the currency dimension.'}),"\n",(0,a.jsx)(t.p,{children:"Some people who can't even grasp the concept of dimensions might ask: what is the dimension of labor? Such people fundamentally don't know what dimension means. It's like asking: \"What is the dimension of the sun?\" -- anyone who asks this basically has never studied physics. Dimension relates to measurement. For example, regarding the sun, if we examine it from the perspective of time, the dimension of the sun's lifespan is the dimension of time; if from the perspective of size, the dimension of the sun's volume is the cube of the length dimension. From this we know that asking \"what is the dimension of the sun?\" only shows that the person doesn't understand dimensions at all! Similarly, asking \"what is the dimension of labor?\" is the same. But from the perspective of value measurement, the dimension of the value of the labor-power commodity is likewise the currency dimension."}),"\n",(0,a.jsx)(t.p,{children:"The ratio relationship of exchange value is formed in commodity exchange on the common basis of the currency dimension. Without value -- this common basis of the currency dimension -- the possibility of commodity exchange cannot exist. Actually, these are all the most basic concepts for understanding Marx, but one must note here that the currency dimension is a result of the historical formation movement of the currency category, not an a priori concept. The movement from the commodity category to the currency category to the capital category constitutes the developmental history of capitalism."}),"\n",(0,a.jsx)(t.p,{children:"In short, my advice to those who oppose Marx: Marx is not beyond criticism, especially in the academic domain where open research is perfectly acceptable. But the prerequisite is that one must first understand Marx, first get Marx's actual ideas straight. If you don't even know what Marx is saying and you're already opposing Marx, don't you think that's a bit too unserious?"})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>r});var o=n(96540);const a={},s=o.createContext(a);function i(e){const t=o.useContext(s);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);